import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
import {equipmentPages,renderEquipmentPage} from './equipment-site-content.js';
export function equipmentCatalog(html){return '<section class="equipment-catalog" aria-label="کالاها و آفیش فروشگاه">'+html.slice(html.indexOf('<body'),html.lastIndexOf('</body>')).replace(/^<body[^>]*>/,'').replace(/<main>/,'<div class="catalog-body"><!--EQUIPMENT_PRODUCTS_HEADING-->').replace('</main>','</div>').replace('<h1 id="title">','<h2 id="title">').replace('</h1>','</h2>').replace(/<a href="#storeAbout">[\s\S]*?<\/a>/,'').replace('href="#rentalSection"','href="/rental-equipment"').replace('href="#catalog"','href="/products"').replace(/<div class="rentalSectionHead">[\s\S]*?<\/div>/,'').replace('رمز عبور حساب فوتوبریج','رمز عبور').replace('با حساب عکاسی فوتوبریج وارد شوید؛ انتخاب تجهیزات، قیمت اجاره، ثبت آفیش و تأیید فروشگاه در همین سایت انجام می‌شود.','').replace(/<p class="muted">حساب عکاسی ندارید[\s\S]*?<\/p>/,'').replace('ثبت‌نام عکاس در فوتوبریج','ثبت‌نام عکاس').replace(/<footer /g,'<div ').replace('</footer>','</div>')+'</section>';}
export async function handleEquipmentSite(req,res,url,domain,shop,d){if(req.method!=='GET')return false;const files={'/site-layout.js':['site-layout.js','application/javascript; charset=utf-8'],'/site-reviews.js':['site-reviews.js','application/javascript; charset=utf-8'],'/equipment-album.js':['equipment-album.js','application/javascript; charset=utf-8'],'/equipment-site.js':['equipment-site.js','application/javascript; charset=utf-8'],'/equipment-site/logo.svg':['equipment-site/logo.svg','image/svg+xml'],'/equipment-site/studio-camera.webp':['equipment-site/studio-camera.webp','image/webp'],'/equipment-site/equipment-kit.webp':['equipment-site/equipment-kit.webp','image/webp'],'/equipment-site.css':['equipment-site.css','text/css; charset=utf-8'],'/lab-storefront.css':['lab-storefront.css','text/css; charset=utf-8']};if(Object.hasOwn(files,url.pathname)){const [file,type]=files[url.pathname];res.writeHead(200,{'content-type':type});res.end(fs.readFileSync(path.join(d.webRoot,file)));return true;}
if(url.pathname==='/robots.txt'){res.writeHead(200,{'content-type':'text/plain'});res.end('User-agent: *\nAllow: /\nDisallow: /api/\nSitemap: https://'+domain.hostname+'/sitemap.xml\n');return true;}
if(url.pathname==='/sitemap.xml'){res.writeHead(200,{'content-type':'application/xml'});res.end('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+equipmentPages(shop).map(([p])=>'<url><loc>https://'+domain.hostname+p+'</loc></url>').join('')+'</urlset>');return true;}
if(!equipmentPages(shop).some(([p])=>p===url.pathname))return false;const saved=(await d.pool.query('SELECT config FROM equipment_public_site_content WHERE shop_id=$1',[shop.id])).rows[0]?.config||{},nonce=crypto.randomBytes(16).toString('base64'),catalog=['/products','/rental-equipment'].includes(url.pathname)?equipmentCatalog(fs.readFileSync(path.join(d.webRoot,'storefront.html'),'utf8')):'',page=renderEquipmentPage(shop,saved,d.publicOrigin,{pathname:url.pathname,hostname:domain.hostname,nonce,catalog});res.writeHead(page.status,{'content-type':'text/html; charset=utf-8','content-security-policy':"default-src 'self'; img-src 'self' https: data:; style-src 'self' 'unsafe-inline'; script-src 'self' 'nonce-"+nonce+"'; connect-src 'self'; font-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'self' https://photobridge.ir"});res.end(page.html);return true;}
